 const analyze=()=>{setLoading(true);setTimeout(()=>{const result=structuredClone(extractedRtpResult);setRtpResult(result);setForm(old=>({...old,sr:result.sr.toFixed(1)}));setSummary(`${form.name||"학생"} 학생은 영어 원서를 읽고 핵심 내용을 파악하는 능력이 뛰어납니다. 특히 어휘와 독해 영역에서 또래 평균 이상의 강점을 보였습니다. 문법에서는 기본 문장 구조를 이해하고 있으나, 과거·현재 시제를 문맥에 맞게 구분하는 연습이 필요합니다.`);setLoading(false);setNotice(rtp?"AI 분석이 완료되었습니다. RTP 결과 요약을 확인해 주세요.":"첨부 파일 없이 기본 정보 기준의 분석 초안을 생성했습니다.")},1200)};
